<?php

declare(strict_types=1);

namespace Juf\DoctrineImportBundle\Definition;

enum IdGeneration: string
{
    /** Value generated by the database (auto-increment, identity column). */
    case Identity = 'IDENTITY';

    /** Value taken from an existing database sequence (PostgreSQL SERIAL columns). */
    case Sequence = 'SEQUENCE';

    /** Value assigned by the application. */
    case None = 'NONE';
}
